(x, y, t) => {
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18+Math.sin(x*0.014+t*0.32)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.012+sy*0.008+t*0.15)*8;
  const w2y = Math.cos(sx*0.008-sy*0.012+t*0.18)*8;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75)*40,0.085,1.8,1]
  ];
  let aS=0,iS=0,cS=0,hS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    cS+=Math.cos(d*f*1.3-t*sp*0.8+ph*2);
    hS+=Math.sin(d*f*0.5-t*sp*1.2+ph*0.5);
  }
  const n=src.length,act=aS/n,inh=iS/n,cross=cS/n,harm=hS/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1)+Math.sin(fx*0.02+fy*0.06-t*0.6))/3;
  const fine=(Math.sin((fx+fy)*0.12+t*2.5)+Math.sin((fx-fy)*0.1-t*2)+Math.sin(fx*0.15+fy*0.08+t*3))*0.33;
  const cx=240,cy=120,dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.9))*0.33;
  let minD=999,minD2=999;
  for(let i=0;i<8;i++){
    const a=i*0.7854+t*0.05,r=60+Math.sin(i*1.7+t*0.3)*30;
    const d=Math.sqrt((fx-cx-Math.cos(a)*r)**2+(fy-cy-Math.sin(a)*r)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2){minD2=d;}
  }
  const voronoi=Math.sin((minD2-minD)*0.3)*0.5;
  const u=act-inh*0.6+bg*0.25+spiral*0.3+voronoi*0.2;
  const v=cross*0.5+harm*0.5+fine*0.2;
  const reaction=Math.tanh(u*2.0+v*0.8);
  const inhibitor=Math.tanh(v*1.5-u*0.5);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.55+inhibitor*0.15+cell*0.15+voronoi*0.15;
  const val=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,85],[18,95,120],[25,155,140],[120,190,90],
    [210,195,60],[220,140,65],[200,90,60],[165,50,70],[100,25,65],
    [55,18,60],[20,15,55],[6,12,52]
  ];
  const idx=val*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const glow=Math.max(0,reaction-0.5)*0.6;
  const edge=Math.abs(reaction)>0.65?1.2:1.0;
  const eGlow=Math.abs(inhibitor)>0.6?1.1:1.0;
  const br=lum*edge*eGlow+glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*br+glow*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*br+glow*30)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*br+glow*50)|0
  ];
}
